Quick code examples to reproduce locally

- Python:
  import base64
  def to_base64(s):
      return base64.b64encode(s.encode('ascii')).decode('ascii')
  def from_base64(s):
      return base64.b64decode(s).decode('ascii')
  mock = "AX-MOCK12345-XYZ"
  encoded = to_base64(mock)
  decoded = from_base64(encoded)
  print(encoded)  # QVgtTU9DSzEyMzQ1LVhZWg==
  print(decoded)  # AX-MOCK12345-XYZ

- JavaScript (browser or Node.js):
  // Encode
  function encodeBase64(s) {
      return btoa(unescape(encodeURIComponent(s)));
  }
  // Decode
  function decodeBase64(s) {
      return decodeURIComponent(escape(atob(s)));
  }
  const mock = "AX-MOCK12345-XYZ";
  const encoded = encodeBase64(mock);
  const decoded = decodeBase64(encoded);
  console.log(encoded); // QVgtTU9DSzEyMzQ1LVhZWg==
  console.log(decoded); // AX-MOCK12345-XYZ

